def verify_golomb_ruler(marks):
    """Verify that a set of marks forms a valid Golomb ruler."""
    distances = []
    for i in range(len(marks)):
        for j in range(i+1, len(marks)):
            d = marks[j] - marks[i]
            if d <= 0:
                return False, "Marks not in increasing order"
            if d in distances:
                return False, f"Duplicate distance: {d}"
            distances.append(d)
    return True, f"Valid Golomb ruler with {len(distances)} unique distances"

# Known optimal Golomb ruler with 9 marks
marks = [0, 1, 5, 12, 25, 27, 35, 41, 44]
valid, msg = verify_golomb_ruler(marks)
print(f"Known ruler: {marks}")
print(f"Valid: {valid}, {msg}")

